// hideWindow keeps the console a package manager would open to itself: the
// output is read from the pipes and shown on the page instead.
func hideWindow(cmd *exec.Cmd) {
	cmd.SysProcAttr = &syscall.SysProcAttr{HideWindow: true}
}

