/** How often the scores are read again while the page is open. */
const refreshMs = 20000;

/** Fills {name} placeholders, which is all the interpolation these strings need. */
function fill(key: string, values: Record<string, string | number>) {
  return Object.entries(values).reduce(
    (text, [name, value]) => text.split(`{${name}}`).join(String(value)),
    i18next.t(key),
  );
}

/**
 * What a row says about itself in one plain sentence, so a state nobody has
 * clicked into still reads as something. A row that failed names the cases it
 * failed: "F" alone is a letter, not a finding.
 */
function stateOf(probe: ProviderProbe | undefined, cases: ProbeCase[]) {
  if (!probe) {
    return i18next.t("audit:Not probed yet");
  }
  if (!probe.ok) {
    return i18next.t("audit:The probe could not run");
  }
  const {alerts, warnings} = probeFindings(probe);
  const names = (checks: typeof alerts) => checks.map(check => checkTitle(check, cases)).join(", ");
  if (alerts.length > 0) {
    return fill("audit:Cases that failed", {names: names(alerts)});
  }
  if (warnings.length > 0) {
    return fill("audit:Cases that were flagged", {names: names(warnings)});
  }
  return i18next.t(gradeStyleOf(probe.grade).label);
}

/** One provider's line: who it is, what it scored, and what failed if anything. */
function ProviderScore({
  provider,
  probe,
  cases,
}: {
  provider: Provider;
  probe?: ProviderProbe;
  /** The suite as it stands now, which is what names a case in the reader's
   * language rather than by the English it was stored under. */
  cases: ProbeCase[];
}) {
  const {alerts, warnings} = probeFindings(probe);
  const name = provider.displayName || provider.name;

  return (
    <Link
      to={`/authenticity?tab=report&provider=${encodeURIComponent(providerIdOf(provider))}`}
      className="hover:border-foreground/20 hover:bg-accent/40 flex min-w-0 items-start gap-2 rounded-lg border px-2.5 py-1.5 transition-colors"
    >
      <ProviderIcon
        icon={provider.icon}
        baseUrl={provider.baseUrl}
        alt={name}
        size={16}
        className="mt-0.5"
      />
      <div className="flex min-w-0 flex-col">
        <span className="truncate text-xs">{name}</span>
        <span className="text-muted-foreground line-clamp-2 text-[11px] leading-snug">
          {stateOf(probe, cases)}
        </span>
      </div>
      <div className="ml-auto flex shrink-0 items-center gap-1.5">
        {alerts.length > 0 ? (
          <Badge variant="danger">{fill("audit:Failed cases", {count: alerts.length})}</Badge>
        ) : warnings.length > 0 ? (
          <Badge variant="warning">{fill("audit:Flagged cases", {count: warnings.length})}</Badge>
        ) : null}
        <ScoreBadge probe={probe} showLabel={false} />
      </div>
    </Link>
  );
}

/** The scores as they stand, re-read while the page is open. */
export function useProviderProbes() {
  const [probes, setProbes] = React.useState<ProviderProbe[]>([]);
  const [mode, setMode] = React.useState<ProviderProbeMode>("auto");
  const [loaded, setLoaded] = React.useState(false);

  React.useEffect(() => {
    const load = () => {
      ProviderBackend.getProviderProbes()
        .then(res => {
          if (res.status !== "ok") {
            return;
          }
          setProbes(res.data ?? []);
          setMode(res.data2 ?? "auto");
        })
        .catch(() => undefined)
        .then(() => setLoaded(true));
    };

    load();
    const interval = setInterval(load, refreshMs);
    return () => clearInterval(interval);
  }, []);

  return {probes: probes, mode: mode, loaded: loaded};
}

/**
 * The scores of the providers in use, worst first, and what they add up to. The
 * headline grade is the worst one held rather than the average: a machine with
 * four honest providers and one that is not is not four fifths fine.
 */
export function authenticityOf(providers: Provider[], probes: ProviderProbe[]) {
  const configured = providers.filter(provider => provider.status !== "disabled");
  const byProvider = new Map(probes.map(probe => [probe.provider, probe]));
  const scored = configured
    .map(provider => ({provider: provider, probe: byProvider.get(providerIdOf(provider))}))
    .sort((left, right) => {
      const score = (entry: {probe?: ProviderProbe}) =>
        entry.probe?.ok && entry.probe.grade !== "unknown" ? entry.probe.score : Number.POSITIVE_INFINITY;
      return score(left) - score(right);
    });

  return {
    configured: configured,
    scored: scored,
    summary: summarizeAuthenticity(
      scored.filter(entry => entry.probe).map(entry => entry.probe as ProviderProbe),
      configured.length,
    ),
    worst: scored.find(entry => entry.probe?.ok && entry.probe.grade !== "unknown")?.probe,
  };
}

/**
 * Whether the APIs on this machine are what they are sold as, in one card. It
 * is measured without being asked for: every provider is probed when it is
 * added and again once its report goes stale, so this says something before
 * anyone thinks to check.
 */
export function AuthenticityOverview({
  providers,
  showLink = true,
  className,
}: {
  providers: Provider[];
  /** False on the page this links to, where the link would point at itself. */
  showLink?: boolean;
  className?: string;
}) {
  const [cases, setCases] = React.useState<ProbeCase[]>([]);
  const {probes, mode, loaded} = useProviderProbes();

  // Read once: the suite names the cases a row failed, and it does not change
  // while a page is open.
  React.useEffect(() => {
    ProbeCaseBackend.getProbeCases()
      .then(res => setCases(res.status === "ok" ? (res.data ?? []) : []))
      .catch(() => undefined);
  }, []);

  const {configured, scored, summary, worst} = authenticityOf(providers, probes);
  const style = gradeStyleOf(worst?.grade);

  if (configured.length === 0) {
    return null;
  }

  return (
    <Card className={cn("gap-0 py-0 shadow-xs", className)}>
      <CardContent className="flex flex-col gap-3 p-4">
        <div className="flex flex-wrap items-center gap-3">
          <ScoreDial probe={worst} size={56} />
          <div className="flex min-w-0 flex-col gap-0.5">
            <div className="flex items-center gap-1.5">
              <ShieldCheck className="text-muted-foreground size-3.5" />
              <span className="text-sm font-medium">{i18next.t("audit:Authenticity")}</span>
              <GradeScaleTip />
            </div>
            <span className="text-xs">
              {summary.graded === 0
                ? i18next.t(mode === "off" ? "audit:Probing is off" : "audit:Measuring now")
                : i18next.t(style.verdict)}
            </span>
            <span className="text-muted-foreground text-[11px]">
              {fill("audit:Graded providers", {
                graded: summary.graded,
                total: configured.length,
              })}
              {summary.alerting > 0 ? ` · ${fill("audit:Providers alerting", {count: summary.alerting})}` : ""}
              {summary.ungraded > 0 ? ` · ${fill("audit:Providers unmeasured", {count: summary.ungraded})}` : ""}
            </span>
          </div>

          {showLink ? (
            <Button asChild variant="outline" size="sm" className="ml-auto">
              <Link to="/authenticity">
                <ShieldCheck />
                {i18next.t("audit:See the evidence")}
              </Link>
            </Button>
          ) : null}
        </div>

        {loaded ? (
          <div className="grid grid-cols-1 gap-2 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
            {scored.map(entry => (
              <ProviderScore
                key={providerIdOf(entry.provider)}
                provider={entry.provider}
                probe={entry.probe}
                cases={cases}
              />
            ))}
          </div>
        ) : null}
      </CardContent>
    </Card>
  );
}

